+import { useState, useEffect } from 'react';
+
+const ECOSYSTEM_PREFS_KEY = '@anymd/ecosystem-master-prefs';
+
+export interface DomainState {
+  activeVault: string;
+  themePalette: 'bubblegum' | 'sage' | 'manila' | 'iris' | 'lavender';
+  isVaultMounted: boolean;
+  sipCount: number;
+  lastExcretionDurationSec: number;
+  lastExcretionType: 'pee' | 'poop' | null;
+  sipPeeRatio: number;
+  hyperboleCount: number;
+  somaticComfortMode: boolean;
+}
+
+const DEFAULT_STATE: DomainState = {
+  activeVault: 'LCMD Primary',
+  themePalette: 'bubblegum',
+  isVaultMounted: false,
+  sipCount: 0,
+  lastExcretionDurationSec: 0,
+  lastExcretionType: null,
+  sipPeeRatio: 3.5,
+  hyperboleCount: 0,
+  somaticComfortMode: true
+};
+
+export const useMasterEcosystemState = () => {
+  const [state, setStateState] = useState<DomainState>(() => {
+    try {
+      const stored = localStorage.getItem(ECOSYSTEM_PREFS_KEY);
+      return stored ? { ...DEFAULT_STATE, ...JSON.parse(stored) } : DEFAULT_STATE;
+    } catch (e) {
+      return DEFAULT_STATE;
+    }
+  });
+
+  const setState = (updates: Partial<DomainState>) => {
+    setStateState(prev => {
+      const updated = { ...prev, ...updates };
+      // Recalculate Sips-to-Pee ratios
+      if (updates.sipCount !== undefined) {
+        // Simple internal ratio updates
+        const peeEquivalent = prev.lastExcretionType === 'pee' ? 1 : 0.5;
+        updated.sipPeeRatio = Number((updated.sipCount / Math.max(1, peeEquivalent)).toFixed(2));
+      }
+      localStorage.setItem(ECOSYSTEM_PREFS_KEY, JSON.stringify(updated));
+      return updated;
+    });
+  };
+
+  useEffect(() => {
+    const handleStorageChange = (e: StorageEvent) => {
+      if (e.key === ECOSYSTEM_PREFS_KEY && e.newValue) {
+        setStateState(JSON.parse(e.newValue));
+      }
+    };
+    window.addEventListener('storage', handleStorageChange);
+    return () => window.removeEventListener('storage', handleStorageChange);
+  }, []);
+
+  return { state, setState };
+};

